// alwaysOutputData:true liefert bei 0 offenen Zeilen ein Platzhalter-Item ohne id - anhand
// des Pflichtfelds id von einem echten Treffer unterscheiden (gleiches Prinzip wie in
// Workflow 15/16).
const items = $input.all().map(i => i.json).filter(j => j && j.id !== undefined && j.id !== null);
if (items.length === 0) {
  return [{ json: { _placeholder: true } }];
}
return items;

// Baut das news_batch-Array fuer die KI. Anders als 03 wird betroffene_ticker NICHT von der
// KI neu ermittelt (Halluzinationsrisiko), sondern die bereits deterministisch in Workflow 16
// ermittelte Zuordnung (vorgeschlagene_ticker) wird der KI zur PRUEFUNG vorgelegt - sie
// bestaetigt oder verwirft, erfindet aber keine neuen Ticker.
const items = $input.all().map(i => i.json);
const news_batch = items.map(j => ({
  id: j.id,
  titel: j.title,
  beschreibung: j.raw_content || '',
  vorgeschlagene_ticker: Array.isArray(j.linked_tickers_json) ? j.linked_tickers_json : (Array.isArray(j.ambiguous_candidates_json) ? j.ambiguous_candidates_json : []),
  ist_markt_makro: j.is_general_market === true
}));
return [{ json: { news_batch, _originals: items } }];

// ==========================================================================================
// PLATZHALTER - MUSS MANUELL ERSETZT WERDEN durch einen echten OpenAI-Node
// (Typ n8n-nodes-langchain.openAi, wie "KI: Nachricht bewerten" in Workflow 03).
// Modell z.B. gpt-5.4-mini, Credential "OpenAI account".
//
// SYSTEM-PROMPT (als "system"-Message):
// -------------------------------------------------------------------------------------------
// Du bist ein sachlicher Aktien-News-Analyst fuer die historische Simulation eines
// automatisierten Aktien-Beobachtungssystems (KEIN Live-Betrieb - diese Nachrichten liegen
// in der Vergangenheit und werden fuer Backtesting verwendet).
//
// WICHTIGE EINSCHRAENKUNG: Du erhaeltst nur Titel und (falls vorhanden) eine
// Kurzbeschreibung, NIEMALS den vollstaendigen Artikeltext (Datenquelle: GDELT Article
// List, liefert grundsaetzlich keinen Volltext). Beruecksichtige diese Einschraenkung
// explizit in deiner Datenqualitaetsbewertung.
//
// Deine Aufgabe: Bewerte ALLE Nachrichten im uebergebenen Array. Fuer jede Nachricht wurde
// bereits automatisch (NICHT durch dich) anhand von Firmennamen/Aliasen eine vorlaeufige
// Ticker-Zuordnung ermittelt (Feld vorgeschlagene_ticker) oder als allgemeine
// Markt-/Makronachricht eingestuft (ist_markt_makro=true). Diese Zuordnung kann falsch/
// irrelevant sein (z.B. "BMW" als Automarke in einem Verkehrsunfall statt als Boersentitel)
// - PRUEFE KRITISCH, ob tatsaechlich ein boersenrelevanter Bezug besteht, uebernimm die
// Vorschlaege nicht unbesehen.
//
// Regeln:
// - Keine Anlageberatung, keine Kauf-/Verkaufsempfehlungen, keine erfundenen Fakten.
// - Antworte ausschliesslich mit einem validen JSON-Array. Kein Markdown, kein Text davor
//   oder danach.
//
// Bewertungsfelder pro Nachricht:
// - id: (gleiche id wie im Input)
// - relevanz: "hoch" | "mittel" | "niedrig" | "irrelevant"
// - relevanz_konfidenz: 0-100
// - sentiment: "positiv" | "negativ" | "neutral" | "unklar"
// - kurswirkung: "steigend" | "fallend" | "keine" | "unklar"
// - wahrscheinlichkeit_positiv, wahrscheinlichkeit_negativ, wahrscheinlichkeit_neutral: je
//   0-1, muessen zusammen (fast) genau 1 ergeben
// - bezug: kurze Erklaerung
// - news_kategorie: genau einer von quarterly_results, profit_warning, forecast_change,
//   merger_acquisition, regulation, management_change, legal_dispute, product_news, macro,
//   geopolitics, analyst_rating, other
// - begruendung: ein Satz Begruendung
// - bestaetigte_ticker: JSON-Array, NUR aus vorgeschlagene_ticker uebernehmen, was du
//   tatsaechlich fuer zutreffend haeltst. Leer [] wenn keiner zutrifft. Keine neuen Ticker
//   erfinden.
// - wirkungsebene: "einzeltitel" | "sektor" | "markt" | "makro" | "unklar"
// - wirkungsrichtung: "positiv" | "negativ" | "neutral" | "unklar"
// - wirkung_staerke: "hoch" | "mittel" | "niedrig"
// - staerke_konfidenz: 0-100
// - datenqualitaet_score: 0-100, IMMER unter Beruecksichtigung dass kein Volltext vorliegt
// - begruendung_tickerbezug: kurze Begruendung. Leer wenn kein Tickerbezug.
//
// USER-MESSAGE:
// -------------------------------------------------------------------------------------------
// Nachrichten:
// ${JSON.stringify($json.news_batch)}
//
// Antworte NUR mit einem JSON-Array der Form:
// [{"id":0,"relevanz":"...","relevanz_konfidenz":80,"sentiment":"...","kurswirkung":"...",
//   "wahrscheinlichkeit_positiv":0.3,"wahrscheinlichkeit_negativ":0.2,
//   "wahrscheinlichkeit_neutral":0.5,"bezug":"...","news_kategorie":"...","begruendung":"...",
//   "bestaetigte_ticker":[],"wirkungsebene":"...","wirkungsrichtung":"...",
//   "wirkung_staerke":"...","staerke_konfidenz":70,"datenqualitaet_score":85,
//   "begruendung_tickerbezug":"..."},...]
// ==========================================================================================
throw new Error('PLATZHALTER: Diesen Node durch einen echten OpenAI-Node ersetzen (siehe Kommentar im Code dieses Platzhalter-Nodes fuer den vollstaendigen Prompt).');

// Analog 03s "KI-Bewertung aufbereiten", angepasst: keine Watchlist-Pruefung der Ticker
// noetig (die KI bestaetigt/verwirft nur aus der bereits deterministisch ermittelten
// vorgeschlagene_ticker-Liste, erfindet keine neuen - siehe Prompt im Platzhalter-Node).
function getAiText(resp) {
  if (typeof resp === 'string') return resp;
  if (resp && Array.isArray(resp.output)) {
    const msg = resp.output.find(o => o.type === 'message');
    const part = msg && Array.isArray(msg.content) ? msg.content.find(c => c.type === 'output_text') : null;
    if (part && part.text) return part.text;
  }
  if (resp && resp.choices && resp.choices[0] && resp.choices[0].message) return resp.choices[0].message.content || '';
  if (resp && typeof resp.content === 'string') return resp.content;
  return JSON.stringify(resp || '');
}

function parseKiArray(text) {
  let t = String(text || '').trim();
  t = t.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  try {
    const p = JSON.parse(t);
    if (Array.isArray(p)) return p;
  } catch (e) {}
  const start = t.indexOf('[');
  const end = t.lastIndexOf(']');
  if (start >= 0 && end > start) {
    try {
      const p = JSON.parse(t.substring(start, end + 1));
      if (Array.isArray(p)) return p;
    } catch (e) {}
  }
  return null;
}

function confNum(v, min, max) {
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  return Math.min(max, Math.max(min, n));
}

function probTriple(pos, neg, neu) {
  const p = Number(pos), n = Number(neg), z = Number(neu);
  if (![p, n, z].every(Number.isFinite)) return { positive: null, negative: null, neutral: null };
  const sum = p + n + z;
  if (sum < 0.99 || sum > 1.01) return { positive: null, negative: null, neutral: null };
  return { positive: p, negative: n, neutral: z };
}

const originals = $('Baue Batch-Payload').item.json._originals;
const rawText = getAiText($json);
const bewertungen = parseKiArray(rawText);

const results = [];

if (!bewertungen) {
  for (const orig of originals) {
    results.push({ json: { _action: 'retry', _error: 'KI-Antwort nicht als JSON-Array parsebar' } });
  }
  return results;
}

const byId = new Map(bewertungen.filter(x => x && x.id !== undefined).map(x => [String(x.id), x]));

for (const orig of originals) {
  const b = byId.get(String(orig.id));
  if (!b) {
    results.push({ json: { _action: 'retry', _error: 'Keine Bewertung fuer diese News in der KI-Antwort enthalten', news_id: orig.id } });
    continue;
  }
  const relevant = b.relevanz && b.relevanz !== 'irrelevant';

  const vorgeschlagen = Array.isArray(orig.linked_tickers_json) ? orig.linked_tickers_json : (Array.isArray(orig.ambiguous_candidates_json) ? orig.ambiguous_candidates_json : []);
  const vorgeschlagenSet = new Set(vorgeschlagen.map(t => String(t).trim()));
  const gemeldeteTicker = Array.isArray(b.bestaetigte_ticker) ? b.bestaetigte_ticker : [];
  // Verteidigung in der Tiefe: nur Ticker uebernehmen, die tatsaechlich unter den
  // deterministisch vorgeschlagenen waren - eine von der KI neu "erfundene" Zuordnung wird
  // nicht durchgereicht (gleiches Prinzip wie 03s Watchlist-Filter, hier gegen die eigene
  // Vorschlagsliste statt gegen die Watchlist).
  const bestaetigteTickerGeprueft = gemeldeteTicker.filter(t => vorgeschlagenSet.has(String(t).trim()));

  const wahrscheinlichkeiten = probTriple(b.wahrscheinlichkeit_positiv, b.wahrscheinlichkeit_negativ, b.wahrscheinlichkeit_neutral);

  results.push({ json: {
    _action: 'persist',
    news_id: orig.id,
    relevant,
    wirkungsebene: b.wirkungsebene || 'unklar',
    betroffene_ticker: bestaetigteTickerGeprueft,
    wirkungsrichtung: ['positiv','negativ','neutral','unklar'].includes(b.wirkungsrichtung) ? b.wirkungsrichtung : 'unklar',
    wirkung_staerke: ['hoch','mittel','niedrig','unklar'].includes(b.wirkung_staerke) ? b.wirkung_staerke : 'unklar',
    sentiment: b.sentiment || 'unklar',
    konfidenz: confNum(b.relevanz_konfidenz, 0, 100),
    news_kategorie: ['quarterly_results','profit_warning','forecast_change','merger_acquisition','regulation','management_change','legal_dispute','product_news','macro','geopolitics','analyst_rating','other'].includes(b.news_kategorie) ? b.news_kategorie : 'other',
    ticker_begruendung: b.begruendung_tickerbezug || '',
    wirkungs_begruendung: b.begruendung || '',
    based_on_full_text: orig.has_full_text === true
  } });
}

return results;

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'[]'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

const j = $json;
let sql;

if (j._action === 'persist') {
  sql = `INSERT INTO trading.historical_news_assessments
    (news_id, relevant, wirkungsebene, betroffene_ticker_json, wirkungsrichtung, wirkung_staerke,
     sentiment, konfidenz, news_kategorie, ticker_begruendung, wirkungs_begruendung,
     based_on_full_text, modell_version, prompt_version)
    VALUES (${pgNum(j.news_id)}, ${pgBool(j.relevant)}, ${pgStr(j.wirkungsebene)}, ${pgJsonb(j.betroffene_ticker)},
            ${pgStr(j.wirkungsrichtung)}, ${pgStr(j.wirkung_staerke)}, ${pgStr(j.sentiment)}, ${pgNum(j.konfidenz)},
            ${pgStr(j.news_kategorie)}, ${pgStr(j.ticker_begruendung)}, ${pgStr(j.wirkungs_begruendung)},
            ${pgBool(j.based_on_full_text)}, ${pgStr('gpt-5.4-mini')}, ${pgStr('historische-news-v1')});`;
} else {
  // Kein Retry-Zaehler auf historical_news (anders als news_items) - ein fehlgeschlagenes
  // Item bleibt einfach ohne Bewertungszeile und wird beim naechsten Worker-Lauf automatisch
  // erneut aufgegriffen (kein Live-Zeitdruck bei historischen Daten, im Unterschied zu 03).
  // Ein reiner SQL-Kommentar ohne echtes Statement koennte je nach Treiberverhalten als
  // leere/ungueltige Query abgelehnt werden - stattdessen ein echtes, harmloses No-Op.
  sql = `SELECT 1; -- retry, kein Insert: ${String(j._error || 'unbekannter Fehler').replace(/[\r\n]/g, ' ')}`;
}

return { json: { ...j, sql } };
